import { useState, type Dispatch, type SetStateAction } from 'react';

// Route changes unmount the page component, so plain useState loses everything
// when you navigate to another tool and back. This caches the value in a
// module-level map that outlives the component — state survives switching
// tools for the rest of the browser tab's session, and resets on a hard
// reload (no localStorage/sessionStorage involved, intentionally — avoids
// serialization edge cases for things like an uploaded logo data URL).
const cache = new Map<string, unknown>();

export function usePersistentState<T>(key: string, initialValue: T | (() => T)): [T, Dispatch<SetStateAction<T>>] {
  const [state, setState] = useState<T>(() => {
    if (cache.has(key)) return cache.get(key) as T;
    return initialValue instanceof Function ? initialValue() : initialValue;
  });

  const setPersistentState: Dispatch<SetStateAction<T>> = (value) => {
    setState((prev) => {
      const next = value instanceof Function ? value(prev) : value;
      cache.set(key, next);
      return next;
    });
  };

  return [state, setPersistentState];
}
